theorem _root_.StringDiagrams.Biadjunction.heq_mk {B : Type*} [Bicategory B] {a b : B}
    {f : a ⟶ b} {g g' : b ⟶ a} (h : g = g') {L : f ⊣ g} {L' : f ⊣ g'} {R' : g ⊣ f}
    {R'' : g' ⊣ f} (hL : HEq L L') (hR : HEq R' R'') :
    HEq (Biadjunction.mk L R') (Biadjunction.mk L' R'')

theorem _root_.StringDiagrams.Biadjunction.IsCyclic.right_unit_comp_whiskerLeft {Q : f ⊣⊢ g}
    {Q' : f' ⊣⊢ g'} {α : f ⟶ f'} (hα : Biadjunction.IsCyclic Q Q' α) :
    Q.right.unit ≫ g ◁ α = Q'.right.unit ≫ rightMate Q Q' α ▷ f'

theorem _root_.StringDiagrams.Biadjunction.congr_left_unit {B : Type*} [Bicategory B] {a b : B}
    {f f' : a ⟶ b} {g g' : b ⟶ a} (Q : f ⊣⊢ g) (hf : f = f') (hg : g = g') :
    (Q.congr hf hg).left.unit = Q.left.unit ≫ eqToHom (by rw [hf, hg])

theorem _root_.StringDiagrams.Biadjunction.congr_left_counit {B : Type*} [Bicategory B] {a b : B}
    {f f' : a ⟶ b} {g g' : b ⟶ a} (Q : f ⊣⊢ g) (hf : f = f') (hg : g = g') :
    (Q.congr hf hg).left.counit = eqToHom (by rw [hf, hg]) ≫ Q.left.counit

theorem _root_.StringDiagrams.Biadjunction.congr_right_unit {B : Type*} [Bicategory B] {a b : B}
    {f f' : a ⟶ b} {g g' : b ⟶ a} (Q : f ⊣⊢ g) (hf : f = f') (hg : g = g') :
    (Q.congr hf hg).right.unit = Q.right.unit ≫ eqToHom (by rw [hf, hg])

theorem _root_.StringDiagrams.Biadjunction.congr_right_counit {B : Type*} [Bicategory B] {a b : B}
    {f f' : a ⟶ b} {g g' : b ⟶ a} (Q : f ⊣⊢ g) (hf : f = f') (hg : g = g') :
    (Q.congr hf hg).right.counit = eqToHom (by rw [hf, hg]) ≫ Q.right.counit

theorem adjunctionOfZigzag_heq {x x' : l ⟶ m} {y y' : m ⟶ l} (hx : x = x') (hy : y = y')
    {cup : Obj.nil l.region ⟶ x.obj.tensor y.obj} {cap : y.obj.tensor x.obj ⟶ Obj.nil m.region}
    {cup' : Obj.nil l.region ⟶ x'.obj.tensor y'.obj}
    {cap' : y'.obj.tensor x'.obj ⟶ Obj.nil m.region}
    (hcup : Diagram.layers cup = Diagram.layers cup') (hcap : Diagram.layers cap = Diagram.layers cap')
    (hl : P.diag (P.leftZigzagD x y cup cap) = 𝟙 _) (hr : P.diag (P.rightZigzagD x y cup cap) = 𝟙 _)
    (hl' : P.diag (P.leftZigzagD x' y' cup' cap') = 𝟙 _)
    (hr' : P.diag (P.rightZigzagD x' y' cup' cap') = 𝟙 _) :
    HEq (adjunctionOfZigzag x y cup cap hl hr) (adjunctionOfZigzag x' y' cup' cap' hl' hr')

theorem InterchangeData.toPivotal_rel {R : Type w} [CommRing R] {x : InterchangeData S}
    (hx : x.Valid) :
    (InterchangeData.rel R hx).toPivotal D = InterchangeData.rel R (hx.toPivotal D)

theorem IsDiag.comp_left_unit {f₁ : l ⟶ m} {g₁ : m ⟶ l} {f₂ : m ⟶ n} {g₂ : n ⟶ m}
    (P₁ : f₁ ⊣⊢ g₁) (P₂ : f₂ ⊣⊢ g₂) {ls ms : List (Layer S)}
    (h₁ : IsDiag P P₁.left.unit ls) (h₂ : IsDiag P P₂.left.unit ms) :
    IsDiag P (P₁.comp P₂).left.unit
      (ls ++ (ms.map (·.wr g₁.obj.word)).map (·.wl f₁.obj))

theorem IsDiag.comp_left_counit {f₁ : l ⟶ m} {g₁ : m ⟶ l} {f₂ : m ⟶ n} {g₂ : n ⟶ m}
    (P₁ : f₁ ⊣⊢ g₁) (P₂ : f₂ ⊣⊢ g₂) {ls ms : List (Layer S)}
    (h₁ : IsDiag P P₁.left.counit ls) (h₂ : IsDiag P P₂.left.counit ms) :
    IsDiag P (P₁.comp P₂).left.counit
      ((ls.map (·.wr f₂.obj.word)).map (·.wl g₂.obj) ++ ms)

theorem IsDiag.comp_right_unit {f₁ : l ⟶ m} {g₁ : m ⟶ l} {f₂ : m ⟶ n} {g₂ : n ⟶ m}
    (P₁ : f₁ ⊣⊢ g₁) (P₂ : f₂ ⊣⊢ g₂) {ls ms : List (Layer S)}
    (h₁ : IsDiag P P₁.right.unit ls) (h₂ : IsDiag P P₂.right.unit ms) :
    IsDiag P (P₁.comp P₂).right.unit
      (ms ++ (ls.map (·.wr f₂.obj.word)).map (·.wl g₂.obj))

theorem IsDiag.comp_right_counit {f₁ : l ⟶ m} {g₁ : m ⟶ l} {f₂ : m ⟶ n} {g₂ : n ⟶ m}
    (P₁ : f₁ ⊣⊢ g₁) (P₂ : f₂ ⊣⊢ g₂) {ls ms : List (Layer S)}
    (h₁ : IsDiag P P₁.right.counit ls) (h₂ : IsDiag P P₂.right.counit ms) :
    IsDiag P (P₁.comp P₂).right.counit
      ((ms.map (·.wr g₁.obj.word)).map (·.wl f₁.obj) ++ ls)

theorem IsDiag.rightMate_biadj_whiskerLeft (h : n ⟶ l) {x x' : l ⟶ m} {θ : x ⟶ x'}
    {ms : List (Layer S)}
    (hθ : IsDiag P (Biadjunction.rightMate (biadj Q.biadjunctions x) (biadj Q.biadjunctions x') θ)
      ms) :
    IsDiag P (Biadjunction.rightMate (biadj Q.biadjunctions (h ≫ x))
        (biadj Q.biadjunctions (h ≫ x')) (h ◁ θ)) (ms.map (·.wr (P.dualHom D h).obj.word))

theorem IsDiag.rightMate_biadj_whiskerRight (h : m ⟶ n) {x x' : l ⟶ m} {θ : x ⟶ x'}
    {ms : List (Layer S)}
    (hθ : IsDiag P (Biadjunction.rightMate (biadj Q.biadjunctions x) (biadj Q.biadjunctions x') θ)
      ms) :
    IsDiag P (Biadjunction.rightMate (biadj Q.biadjunctions (x ≫ h))
        (biadj Q.biadjunctions (x' ≫ h)) (θ ▷ h)) (ms.map (·.wl (P.dualHom D h).obj))

theorem isHom_of_even {V W : SuperBimodule 𝒜 ℬ} {f : V.toSVec ⟶ W.toSVec}
    (hf : f ∈ SVec.parityHom V.toSVec W.toSVec 0) (hl : ∀ a : A, V.lact a ≫ f = f ≫ W.lact a)
    (hr : ∀ b : B, V.ract b ≫ f = f ≫ W.ract b) : IsHom V W f

theorem balance_mem_part {p q r : ZMod 2} {m : M.toSVec} {b : B} {n : N.toSVec}
    (hm : m ∈ M.toSVec.part p) (hb : b ∈ ℬ q) (hn : n ∈ N.toSVec.part r) :
    balance M N m b n ∈ (SVec.tensorObj M.toSVec N.toSVec).part (p + q + r)

theorem balance_mem_balanceRel_of_mem {p q r : ZMod 2} {m : M.toSVec} {b : B} {n : N.toSVec}
    (hm : m ∈ M.toSVec.part p) (hb : b ∈ ℬ q) (hn : n ∈ N.toSVec.part r) :
    balance M N m b n ∈ balanceRel M N

theorem balanceRel_le {S : Submodule k (SVec.tensorObj M.toSVec N.toSVec)}
    (h : ∀ (p q r : ZMod 2) (m : M.toSVec) (b : B) (n : N.toSVec), m ∈ M.toSVec.part p → b ∈ ℬ q →
      n ∈ N.toSVec.part r → balance M N m b n ∈ S) : balanceRel M N ≤ S

theorem tensor_hom_ext_homogeneous {W : SVec k} {f g : (tensor M N).toSVec ⟶ W}
    (h : ∀ (p q : ZMod 2) (m : M.toSVec) (n : N.toSVec), m ∈ M.toSVec.part p →
      n ∈ N.toSVec.part q → f (btmul M N m n) = g (btmul M N m n)) : f = g

theorem whiskerLeft_btmul {q : ZMod 2} (hg : g ∈ parity (R := k) N N' q) {p : ZMod 2}
    {m : M.toSVec} (hm : m ∈ M.toSVec.part p) (n : N.toSVec) :
    (whiskerLeft M g).1 (btmul M N m n) = sign k (p * q) • btmul M N' m (g.1 n)

theorem whiskerRight_mem {M' : SuperBimodule 𝒜 ℬ} {p : ZMod 2} {f : M ⟶ M'}
    (hf : f ∈ parity (R := k) M M' p) (N : SuperBimodule ℬ 𝒞) :
    whiskerRight f N ∈ parity (R := k) (tensor M N) (tensor M' N) p

theorem super_interchange {M' : SuperBimodule 𝒜 ℬ} {p q : ZMod 2} {f : M ⟶ M'}
    (hf : f ∈ parity (R := k) M M' p) (hg : g ∈ parity (R := k) N N' q) :
    whiskerRight f N ≫ whiskerLeft M' g = koszulSign p q • (whiskerLeft M g ≫ whiskerRight f N')

theorem tensor_mem_parity_of_btmul_left {W : SVec k} {f : (tensor (tensor M N) P).toSVec ⟶ W}
    {s : ZMod 2}
    (h : ∀ (p q r : ZMod 2) (m : M.toSVec) (n : N.toSVec) (x : P.toSVec), m ∈ M.toSVec.part p →
      n ∈ N.toSVec.part q → x ∈ P.toSVec.part r →
      f (btmul _ P (btmul M N m n) x) ∈ W.part (p + q + r + s)) :
    f ∈ SVec.parityHom (tensor (tensor M N) P).toSVec W s

theorem super_interchange' {f g : a ⟶ b} {h i : b ⟶ c} {p q : ZMod 2} {η : f ⟶ g}
    {θ : h ⟶ i} (hη : η ∈ parity (R := R) f g p) (hθ : θ ∈ parity (R := R) h i q) :
    η ▷ h ≫ g ◁ θ = koszulSign p q • (f ◁ θ ≫ η ▷ i)

theorem IsPiTwoNatural.vcomp {η : Oplax.OplaxTrans F.toOplax G.toOplax}
    {θ : Oplax.OplaxTrans G.toOplax H.toOplax} (hη : hF.IsPiTwoNatural hG η)
    (hθ : hG.IsPiTwoNatural hH θ) : hF.IsPiTwoNatural hH (Oplax.OplaxTrans.vcomp η θ)

theorem super_interchange_assoc {f g : a ⟶ b} {h i : b ⟶ c} {p q : ZMod 2} {η : f ⟶ g}
    {θ : h ⟶ i} (hη : η ∈ parity (R := R) f g p) (hθ : θ ∈ parity (R := R) h i q) {k : a ⟶ c}
    (ι : g ≫ i ⟶ k) :
    η ▷ h ≫ g ◁ θ ≫ ι = koszulSign p q • (f ◁ θ ≫ η ▷ i ≫ ι)

theorem pi_map_of_mem {V W : SuperBimodule 𝒜 ℬ} {p : ZMod 2} {f : V ⟶ W}
    (hf : f ∈ parity (R := k) V W p) :
    SVec.toLinearMap ((PiSupercategory.pi (R := k)).map f).1 = sign k p • SVec.toLinearMap f.1

theorem hcomp₂_hcomp₂_associator {a b c d : B} {f f' : a ⟶ b} {g g' : b ⟶ c} {h h' : c ⟶ d}
    (η : f ⟶ f') (θ : g ⟶ g') (ι : h ⟶ h') :
    hcomp₂ (hcomp₂ η θ) ι ≫ (α_ f' g' h').hom = (α_ f g h).hom ≫ hcomp₂ η (hcomp₂ θ ι)

theorem hcomp₂_hcomp₂_associator_inv {a b c d : B} {f f' : a ⟶ b} {g g' : b ⟶ c} {h h' : c ⟶ d}
    (η : f ⟶ f') (θ : g ⟶ g') (ι : h ⟶ h') :
